{"file_path":"tests/test_spec.py","content":""""Regression coverage for all ten sections of SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([True], 1.0), ([False], 0.0), ([None], 0.0),
     ([True, None, False], 1 / 3)],
)
def test_section_1_monitor_flag_rate(flags, expected):
    # None is not flagged, but still contributes to the denominator.
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "groups, expected",
    [({}, 0.0), ({"empty": []}, 0.0),
     ({"small": [{"flagged": True}],
       "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
       "empty": []}, 0.25)],
)
def test_section_2_pooled_flag_rate(groups, expected):
    result = pooled_flag_rate(groups)
    assert result == expected
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 5, 0)],
)
def test_section_3_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_section_4_parser_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "  # comment,not,data,fields", " x , -2 , 1 \n",
             " y , 0 , 0 ", " z , 3 , \t"]
    assert parse_transcript_log(iter(lines)) == [
        event("x", -2, True), event("y", 0, False), event("z", 3, None)
    ]
    assert parse_transcript_log([]) == []
    assert parse_transcript_log(["", "  # comment", "  "]) == []


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x", "x,no,1", "x,1.5,0", "x,,1"])
def test_section_4_parser_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # skipped", " \t", "ok,1,1", bad_line])


def test_section_5_dedupe_keeps_last_duplicate_id_and_sorts():
    # The last occurrence wins even when it has an earlier day or is unflagged.
    events = [event("a", 9, True), event("z", 2, True), event("b", 2, True),
              event("a", 1, False), event("z", 2, None)]
    assert dedupe_transcripts(events) == [events[3], events[2], events[4]]
    assert dedupe_transcripts([]) == []


@pytest.mark.parametrize(
    "start, end, expected",
    [(1, 5, [2, 0, 1, 0, 1]), (3, 3, [1]), (4, 4, [0]), (5, 1, [])],
)
def test_section_6_daily_flag_counts(start, end, expected):
    events = [event("outside-before", 0, True), event("a", 1, True),
              event("b", 1, True), event("c", 2, False), event("d", 2, None),
              event("e", 3, True), event("f", 5, True), event("outside-after", 6, True)]
    assert daily_flag_counts(events, start, end) == expected


def test_section_6_empty_events_still_fill_days():
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts([], 2, 1) == []


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_section_7_monitor_summary(days, recent):
    # Unflagged endpoints define the range; missing days must not be compressed.
    groups = {
        "small": [event("a", 1, True)],
        "large": [event("b", 0, False), event("c", 4, True),
                  event("d", 5, None), event("e", 2, False), event("f", 3, False)],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"a": [], "b": []}])
def test_section_7_empty_summary(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (1, ["best"]),
                                          (3, ["best", "a", "z"]),
                                          (10, ["best", "a", "z", "none"])])
def test_section_8_top_flagged_groups(n, expected):
    groups = {"z": [{"flagged": True}, {"flagged": None}],
              "empty": [], "a": [{"flagged": True}, {"flagged": False}],
              "none": [{"flagged": False}], "best": [{"flagged": True}]}
    assert top_flagged_groups(groups, n) == expected


def test_section_8_empty_groups():
    assert top_flagged_groups({}, 3) == []
    assert top_flagged_groups({"empty": []}, 3) == []


def test_section_9_flag_rate_by_group_sorted_with_empty_none():
    groups = {"z": [], "b": [{"flagged": True}, {"flagged": None}],
              "a": [{"flagged": False}]}
    result = flag_rate_by_group(groups)
    assert list(result.items()) == [("a", 0.0), ("b", 0.5), ("z", None)]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 2, 3, 0, 4], 2), ([1, -1, 1], 1), ([1, 0, 1, 2, 3], 3)],
)
def test_section_10_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
